import{_ as a,o as l,c as e,a2 as r}from"./chunks/framework.Crpw6aS5.js";const m=JSON.parse('{"title":"克莱顿家园","description":"","frontmatter":{"title":"克莱顿家园"},"headers":[],"relativePath":"03_companies/克莱顿家园.md","filePath":"03_companies/克莱顿家园.md"}'),i={name:"03_companies/克莱顿家园.md"};function o(h,t,d,s,n,u){return l(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="克莱顿家园-clayton-homes" tabindex="-1">克莱顿家园（Clayton Homes） <a class="header-anchor" href="#克莱顿家园-clayton-homes" aria-label="Permalink to &quot;克莱顿家园（Clayton Homes）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>英文名</td><td>Clayton Homes</td></tr><tr><td>行业</td><td>预制房屋建造与融资</td></tr><tr><td>总部</td><td>田纳西州诺克斯维尔</td></tr><tr><td>伯克希尔持股</td><td>100%（2003年收购）</td></tr><tr><td>收购价格</td><td>约17亿美元</td></tr><tr><td>创始人</td><td>吉姆·克莱顿（1956年创办）</td></tr><tr><td>现任CEO</td><td>凯文·克莱顿</td></tr></tbody></table><h2 id="核心业务" tabindex="-1">核心业务 <a class="header-anchor" href="#核心业务" aria-label="Permalink to &quot;核心业务&quot;">​</a></h2><p>克莱顿家园是美国最大的预制房屋（manufactured home）建造商：</p><ul><li>年产超过4万套房屋</li><li>提供房屋建造和融资一体化服务</li><li>通过旗下Vanderbilt Mortgage提供贷款</li><li>雇佣约14,000名员工</li></ul><h2 id="收购故事" tabindex="-1">收购故事 <a class="header-anchor" href="#收购故事" aria-label="Permalink to &quot;收购故事&quot;">​</a></h2><h3 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h3><ul><li><strong>2003年8月</strong>：伯克希尔以约17亿美元收购100%股权</li><li>收购机会由田纳西大学学生推荐</li><li>巴菲特看中了预制住房市场的长期潜力</li></ul><h3 id="投资逻辑" tabindex="-1">投资逻辑 <a class="header-anchor" href="#投资逻辑" aria-label="Permalink to &quot;投资逻辑&quot;">​</a></h3><ol><li><strong>可负担住房需求</strong>：美国约22%的住房是预制房屋</li><li><strong>垂直整合模式</strong>：建造+融资一体化</li><li><strong>管理团队</strong>：吉姆·克莱顿和凯文·克莱顿家族经营</li></ol><h2 id="业务模式" tabindex="-1">业务模式 <a class="header-anchor" href="#业务模式" aria-label="Permalink to &quot;业务模式&quot;">​</a></h2><h3 id="预制房屋优势" tabindex="-1">预制房屋优势 <a class="header-anchor" href="#预制房屋优势" aria-label="Permalink to &quot;预制房屋优势&quot;">​</a></h3><ul><li>建造成本低于传统房屋30-40%</li><li>交付时间短</li><li>质量控制好</li><li>适合首次购房者和老年downsizers</li></ul><h3 id="融资业务" tabindex="-1">融资业务 <a class="header-anchor" href="#融资业务" aria-label="Permalink to &quot;融资业务&quot;">​</a></h3><ul><li>Vanderbilt Mortgage提供分期贷款</li><li>通常是15-30年固定利率贷款</li><li>违约率相对较高，但利差可观</li></ul><h2 id="财务表现" tabindex="-1">财务表现 <a class="header-anchor" href="#财务表现" aria-label="Permalink to &quot;财务表现&quot;">​</a></h2><table tabindex="0"><thead><tr><th>年份</th><th>税前收益</th><th>备注</th></tr></thead><tbody><tr><td>2003</td><td>-</td><td>被收购年份</td></tr><tr><td>2020</td><td>超10亿美元</td><td>行业领先盈利</td></tr><tr><td>近年</td><td>稳定盈利</td><td>持续为伯克希尔贡献利润</td></tr></tbody></table><h2 id="巴菲特评价摘录" tabindex="-1">巴菲特评价摘录 <a class="header-anchor" href="#巴菲特评价摘录" aria-label="Permalink to &quot;巴菲特评价摘录&quot;">​</a></h2><blockquote><p>&quot;克莱顿家园是一家独特的公司，建造美国人买得起的房子。&quot; —— 2003年股东信</p></blockquote><blockquote><p>&quot;预制房屋行业有周期性，但我们有耐心等待行业复苏。&quot; —— 2008年股东信</p></blockquote><blockquote><p>&quot;凯文·克莱顿是一位出色的管理者，继续保持着家族经营的传统。&quot; —— 2020年股东信</p></blockquote><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p>1956, 2003, 2004, 2005, 2006, 2007, 2008, 2009, 2010, 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2019, 2020</p><h2 id="相关信件" tabindex="-1">相关信件 <a class="header-anchor" href="#相关信件" aria-label="Permalink to &quot;相关信件&quot;">​</a></h2><ul><li><a href="./../01_letters/2003年/翻译.html">2003年</a></li><li><a href="./../01_letters/2004年/翻译.html">2004年</a></li><li><a href="./../01_letters/2005年/翻译.html">2005年</a></li><li><a href="./../01_letters/2006年/翻译.html">2006年</a></li><li><a href="./../01_letters/2007年/翻译.html">2007年</a></li><li><a href="./../01_letters/2008年/翻译.html">2008年</a></li><li><a href="./../01_letters/2009年/翻译.html">2009年</a></li><li><a href="./../01_letters/2010年/翻译.html">2010年</a></li><li><a href="./../01_letters/2011年/翻译.html">2011年</a></li><li><a href="./../01_letters/2012年/翻译.html">2012年</a></li><li><a href="./../01_letters/2013年/翻译.html">2013年</a></li><li><a href="./../01_letters/2014年/翻译.html">2014年</a></li><li><a href="./../01_letters/2015年/翻译.html">2015年</a></li><li><a href="./../01_letters/2016年/翻译.html">2016年</a></li><li><a href="./../01_letters/2017年/翻译.html">2017年</a></li><li><a href="./../01_letters/2019年/翻译.html">2019年</a></li><li><a href="./../01_letters/2020年/翻译.html">2020年</a></li></ul>',26)])])}const _=a(i,[["render",o]]);export{m as __pageData,_ as default};
